unsigned char lexer__is_digit(unsigned char b) {
    if (GUST_UNLIKELY(--gust_loop_ticks <= 0)) { gust_loop_ticks = GUST_TICK_INTERVAL; gust_yield(); }
    return std_is_digit(b);
}

